import math

def generate_good_numbers_sums(max_val):
    sums = set()
    # We look for distinct positive integers x and y
    for x in range(2, max_val + 1):
        for y in range(x + 1, max_val + 1):
            if math.gcd(x, y) > 1:
                s = x*x + y*y
                sums.add(s)
    return sorted(list(sums))

# Based on the target 20th smallest being 208, we estimate a maximum value needed.
# Since 14^2 + 3^2 = 196 + 9 = 205, and 12^2 + 10^2 = 144 + 100 = 244,
# and the constraint is gcd(x, y) > 1, we need to check up to at least 14 or 15.
# Let's check up to max_val = 20 just to be safe, though smaller should suffice.
MAX_N = 20
sorted_sums = generate_good_numbers_sums(MAX_N)

print(f"Total unique sums found up to N={MAX_N}: {len(sorted_sums)}")
print("The first 25 smallest sums:")
for i in range(min(25, len(sorted_sums))):
    print(f"Rank {i+1}: {sorted_sums[i]}")

if len(sorted_sums) >= 20:
    print(f"The 20th smallest sum is: {sorted_sums[19]}")
else:
    print("Not enough sums found yet.")

import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

coprime_pairs = []
# Systematically check pairs (x, y) with x < y and gcd(x, y) = 1
# Checking up to y=10
for y in range(2, 11):
    for x in range(1, y):
        if gcd(x, y) == 1:
            coprime_pairs.append((x, y))

print("Smallest coprime pairs (x, y) with x < y:")
for pair in coprime_pairs:
    print(pair)

